insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r45-calls-in-the-browser', 'Calls in the browser', 'Make and take calls on the business number in the staff portal, from anywhere, without your own phone number.', array['va/texts-and-calls', 'admin/texts-and-calls-the-quo-phone-line']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 1, 'The phone bar', '[{"caption":"The business number","say":"Calls are made and taken in the browser of the staff portal, on the business number. Your own phone number is never used or shown, wherever you work from.","visual":{"kind":"title","heading":"One number","text":"Customers always see the business number"}},{"caption":"A call comes in","say":"A call to the business number rings the browsers of customer service and Sales who have a staff page open, with Answer and Decline.","visual":{"kind":"chat","lines":[{"who":"app","text":"Incoming call: Answer or Decline"},{"who":"you","text":"Answer"}]}},{"caption":"During a call","say":"During a call the bar has Mute, a keypad and Hang up, with the call''s timer.","visual":{"kind":"list","heading":"In a call","items":["Mute","Keypad","Hang up","The timer"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 2, 'Nobody answers', '[{"caption":"A missed call","say":"Nobody answering gives the caller a short message, and a missed call with its task. Return it first: calls come before texts.","visual":{"kind":"rule","heading":"Missed call","text":"It becomes a task: call back first.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 1, 'Which number does a customer see when you call them from the portal?', '["Your own mobile number","The business number","No number","The office landline only"]'::jsonb, 1, 'Calls from the portal always show the business number.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 2, 'Whose browser rings for a call to the business number?', '["Nobody''s","Customer service and Sales with a staff page open","Only the Admins''","Every field person''s phone"]'::jsonb, 1, 'It rings customer service and Sales with a staff page open.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 3, 'Nobody answers a call. What happens?', '["The call is lost with no trace","The caller hears a short message, and a missed call with its task is made","It rings forever","It goes to your personal phone"]'::jsonb, 1, 'A missed call with its task, to return first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 4, 'Which do you return first: a missed call or a text?', '["The text","The missed call","Neither","Whichever is older"]'::jsonb, 1, 'Calls come before texts.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-calls-in-the-browser'), 5, 'Which controls does the bar have during a call?', '["Only Hang up","Mute, a keypad and Hang up, with the timer","Record and Share","None"]'::jsonb, 1, 'Mute, keypad and Hang up, with the call''s timer.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
