insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r45-bookings-profile-versions', 'Free cars, the renter on file and Restore this version', 'Which cars are free for any dates, requests and offers that fill from the renter''s profile, a total that follows its lines, and putting a confirmed booking back as it was.', array['va/customer-service', 'va/add-a-rental-by-hand', 'admin/requests-offers-and-bookings', 'admin/calendars', 'renter/find-a-car-and-send-a-request']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 1, 'Which cars are free', '[{"caption":"Pick the dates","say":"At the top of Calendar, pick the customer''s pickup and return. Every car says Available or Not available, with the reason and the next free date.","visual":{"kind":"steps","heading":"Free cars","items":["Open Calendar","Pick the pickup and the return","Read Available or Not available"]}},{"caption":"Offer these dates","say":"Offer these dates on a free car starts the offer with the car and the dates filled in.","visual":{"kind":"rule","heading":"One click","text":"Offer these dates starts the offer.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 2, 'The renter on file', '[{"caption":"The request form","say":"A signed-in renter''s request fills itself from their profile: the name, date of birth, licence class and how we reach them. They check it and change anything; drivers they named before are one tap away.","visual":{"kind":"list","heading":"Filled in","items":["Name","Date of birth","Licence class","Phone, email and channel"]}},{"caption":"Out of date","say":"A licence that has expired, or a home address over a year old, is flagged for the renter to update in their profile.","visual":{"kind":"rule","heading":"Flagged","text":"Expired licence or an old address: they update it.","tone":"warn"}},{"caption":"On your offers","say":"On Send an offer and Add a rental, pick a renter on file and their licence, home address and drivers named before show under their name, with anything out of date flagged to ask them about.","visual":{"kind":"chat","lines":[{"who":"app","text":"Licence on file: Class G, expires 2027. Drivers named before: 1"},{"who":"you","text":"Add them"}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 3, 'Money and versions', '[{"caption":"The total follows","say":"Changing the amount of a line on the Money tab changes the booking''s total and balance with it, so no balance appears that nobody owes.","visual":{"kind":"title","heading":"Lines and total agree","text":"A changed line changes the total"}},{"caption":"Versions of this booking","say":"Once a confirmed booking has been changed, Overview lists its versions: before the first change, then one after each change, the newest current.","visual":{"kind":"list","heading":"Each version","items":["Dates and days","The car","Rental charge","Total"]}},{"caption":"Restore this version","say":"Restore this version shows a preview first, then, with your reason, puts back that version''s dates, car, rental charge and fees exactly. Payments are never touched: a difference is a balance or a credit.","visual":{"kind":"steps","heading":"Restore","items":["Restore this version","Read the preview","Type why and restore"]}},{"caption":"The same checks","say":"The same checks as Edit: the car must be free, and customer service and Sales restore only while Program settings let staff change bookings.","visual":{"kind":"rule","heading":"Same as Edit","text":"Car free, and staff may change bookings.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 1, 'Where do you see which cars are free for a customer''s dates?', '["Only by asking Fleet","At the top of Calendar, after picking the pickup and return","On the public site only","In the owner portal"]'::jsonb, 1, 'Pick the dates at the top of Calendar.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 2, 'A signed-in renter opens the request form. What is filled in?', '["Nothing","The details on their profile: name, date of birth, licence class, contact and channel","Their card number","Another renter''s details"]'::jsonb, 1, 'Their own profile fills the form, and they can change it.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 3, 'The renter''s licence on file has expired. What happens?', '["The request is refused","It is flagged for them to update","It is renewed by itself","Nothing"]'::jsonb, 1, 'It is flagged to update.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 4, 'A confirmed booking went from 7 days to 4, then back to 7 at a higher price. How do you put back the first price?', '["Cancel and rebook","Restore this version on version 1, after its preview","Refund by card","Edit each fee by guesswork"]'::jsonb, 1, 'Restore this version puts back the dates, car, rental charge and fees exactly.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-bookings-profile-versions'), 5, 'Does a restore charge or refund the renter?', '["Yes, at once","No: a difference is a balance or a credit, as with any change","Only on weekends","It refunds the deposit"]'::jsonb, 1, 'Payments are never touched.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
