insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r45-field-shifts-checkins', 'Shifts published by themselves and missing check-ins', 'Shifts open by themselves every second day, a shift for any handover or return without one, and adding the photos and readings of past check-ins and check-outs.', array['field/my-hours-and-pay', 'va/fleet', 'admin/people-and-access']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 1, 'Shifts', '[{"caption":"Published by themselves","say":"Shifts are published by themselves, up to 14 days ahead: one shift of 10:00 to 17:00 for one person, every second day. Fleet can add or cancel shifts too.","visual":{"kind":"title","heading":"Every second day","text":"10:00 to 17:00, one person"}},{"caption":"A shift for every job","say":"A handover or a return that no shift covers gets a shift of its own, from 90 minutes before to 90 minutes after, so every job has a shift to claim.","visual":{"kind":"rule","heading":"Every job","text":"An uncovered handover gets its own shift.","tone":"ok"}},{"caption":"Claim it","say":"Claim shifts on My shifts once you passed the academy. A shift nobody holds 48 hours before it starts alerts Fleet and the Admins.","visual":{"kind":"steps","heading":"Claim","items":["Open My shifts","Free to claim","Claim this shift"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 2, 'Missing check-ins', '[{"caption":"On Today","say":"Field staff see Missing check-in and check-out on Today: past rentals they handled or were given, each with Add the photos and readings.","visual":{"kind":"list","heading":"Add","items":["Odometer","Fuel","Damage photos"]}},{"caption":"Fleet gives them","say":"Fleet sees every missing one on the Field jobs page and gives each to a field staff member.","visual":{"kind":"rule","heading":"Fleet assigns","text":"Give to field staff.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 1, 'Which shifts are published by themselves by default?', '["Every day, 6:00 to 23:00","One shift of 10:00 to 17:00, every second day","None: Fleet publishes all","Weekends only"]'::jsonb, 1, 'One shift of 10:00 to 17:00 for one person, every second day.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 2, 'A handover falls at a time no shift covers. What happens?', '["Nothing","A shift of its own is published around it","The booking is cancelled","The renter is told to move it"]'::jsonb, 1, 'Every handover and return gets a shift to claim.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 3, 'Where do you add the photos and readings of a past check-out you handled?', '["By email to Fleet","Missing check-in and check-out on Today, Add the photos and readings","On the renter site","Nowhere"]'::jsonb, 1, 'On Today, under Missing check-in and check-out.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 4, 'Nobody has claimed a shift 48 hours before it starts. What happens?', '["It is deleted","Fleet and the Admins are alerted","It is given to you by itself","Nothing"]'::jsonb, 1, 'An unclaimed shift 48 hours out alerts Fleet and the Admins.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), 5, 'How does Fleet get a missing check-in done?', '["Fills it in from memory","Gives it to a field staff member from the Field jobs page","Asks the renter","Closes the booking"]'::jsonb, 1, 'Fleet gives each missing one to a field staff member.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-r45-field-shifts-checkins'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r45-townhall-agreements', 'The townhall that did not happen, and your agreement', 'A townhall nobody attended or that was cancelled counts nobody absent; staff in Canada get Canadian terms on their agreement.', array['va/your-workday', 'admin/owner-money', 'admin/settings']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 1, 'The townhall', '[{"caption":"Not held","say":"A townhall nobody attended is recorded as not held and counts nobody absent. An Admin can also mark a past one as not held, which clears its absences.","visual":{"kind":"rule","heading":"Nobody absent","text":"A townhall that did not happen is not a miss.","tone":"ok"}},{"caption":"Cancelled ahead","say":"An Admin can cancel an upcoming townhall: no reminders are sent for it, and it counts nobody absent. Two missed townhalls that were held still lock an account.","visual":{"kind":"title","heading":"Cancelled","text":"No reminders, no misses"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 2, 'Your agreement', '[{"caption":"Canadian terms","say":"Staff who live in Canada get Canadian terms on their agreement: Canada, CAD, paid by Interac e-Transfer or direct deposit.","visual":{"kind":"list","heading":"In Canada","items":["Canada","CAD","Interac e-Transfer or direct deposit"]}},{"caption":"A new agreement","say":"An agreement sent or signed with old terms can be redone: the Admin sends a new agreement to sign in your portal. A signed one stays on file as superseded, and your portal stays open until you sign the new one.","visual":{"kind":"steps","heading":"A new agreement","items":["A notice arrives","Check the key values","Sign in your portal"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 1, 'Nobody attended this week''s townhall. Does it count as a miss?', '["Yes, for everyone","No: it is recorded as not held","Only for Sales","Only for field staff"]'::jsonb, 1, 'A townhall nobody attended counts nobody absent.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 2, 'An Admin cancelled next week''s townhall. What happens?', '["You still get reminders","No reminders, and nobody counts as absent","It moves by itself to the next day","Your account locks"]'::jsonb, 1, 'A cancelled townhall sends no reminders and counts nobody absent.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 3, 'You live in Canada. Which terms does your agreement carry?', '["The Philippines, USD, OnlineJobs.ph","Canada, CAD, Interac e-Transfer or direct deposit","Any country you choose","None"]'::jsonb, 1, 'Staff in Canada get Canadian terms.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 4, 'You get a new agreement to sign. What happens to the one you signed before?', '["It is deleted","It stays on file as superseded, and your portal stays open until you sign","Your portal locks at once","It is sent to the renter"]'::jsonb, 1, 'The signed one stays on file, marked superseded.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r45-townhall-agreements'), 5, 'Do missed townhalls that were held still count?', '["No, never","Yes: two missed townhalls that were held still lock an account","Only for Admins","Only in December"]'::jsonb, 1, 'Only townhalls that were held count, and two misses still lock.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
